window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"CxIZRezqyG0","speaker":"Vivian Balakrishnan","role":"Foreign Minister","country":"Singapore","region":"Asia-Pacific","url":"https://www.youtube.com/watch?v=CxIZRezqyG0","date":"20260926","title":"🇸🇬 Singapore - Foreign Minister Addresses United Nations General Debate, 81st Session | #UNGA","seconds":1263,"words":2476,"counts":{"claims":38,"promises":1,"attacks":0},"topics":[{"topic":"AI regulation","share":0.3765,"seconds":476},{"topic":"multilateralism","share":0.1982,"seconds":250},{"topic":"WTO trade","share":0.1733,"seconds":219},{"topic":"UN reform","share":0.1045,"seconds":132},{"topic":"Strait of Hormuz","share":0.0997,"seconds":126},{"topic":"Straits of Malacca","share":0.0478,"seconds":60}],"timeline":[[2,75,null],[77,138,"multilateralism"],[139,203,"multilateralism"],[204,267,"multilateralism"],[268,333,"Strait of Hormuz"],[334,395,"Strait of Hormuz"],[397,457,"Straits of Malacca"],[459,539,"WTO trade"],[541,607,"WTO trade"],[608,680,"WTO trade"],[683,744,"AI regulation"],[746,819,"AI regulation"],[820,886,"AI regulation"],[887,966,"AI regulation"],[968,1031,"AI regulation"],[1032,1100,"AI regulation"],[1101,1167,"AI regulation"],[1168,1230,"UN reform"],[1232,1301,"UN reform"],[1301,1364,"multilateralism"],[1365,1381,null]],"stances":{"multilateralism":"Vivian Balakrishnan argues that international relations driven by raw power endanger smaller states and fail to address global challenges, necessitating shared universal rules.","Strait of Hormuz":"Vivian Balakrishnan asserts that transit passage through the Strait of Hormuz is a binding customary international law right for all states and must be collectively rejected if closed.","Straits of Malacca":"Singapore holds itself to the same standard as other littoral states in keeping the straits open, secure, and accessible.","WTO trade":"Vivian Balakrishnan states that while free trade has historically boosted global GDP, the multilateral trading system has frayed due to unresolved disputes and the return of tariffs.","AI regulation":"Vivian Balakrishnan states that AI offers extraordinary potential but advances faster than the appreciation of its risks, necessitating new rules and institutions.","UN reform":"Vivian Balakrishnan argues that UN reform should focus on strengthening equal standing and delivering practical results rather than reducing the organization's size, while praising Secretary-General Antonio Guterres for his leadership."},"claims":[{"t":77,"quote":"Our interstate relations are increasingly dictated by raw power, where the outcomes are determined on the basis of size, leverage, and coercion.","topic":"multilateralism","kind":"fact"},{"t":106,"quote":"hard power on its own cannot secure supply chains, protect populations from pandemics, or stabilize a warming","topic":"multilateralism","kind":"fact"},{"t":188,"quote":"The World Food Program feeds over a hundred million people a year.","topic":"multilateralism","kind":"number"},{"t":195,"quote":"The common ICAO standards enable a hundred thousand flights to operate safely every day.","topic":"multilateralism","kind":"number"},{"t":204,"quote":"With the ITU, our telecommunications networks and the internet continues to operate safely, smoothly on a planetary","topic":"multilateralism","kind":"fact"},{"t":262,"quote":"In fact, UNCLOS is one of the great achievements of multilateral lawmaking.","topic":"multilateralism","kind":"fact"},{"t":268,"quote":"It was concluded under the presidency of Professor Tommy Koh of Singapore, who called it the constitution for the oceans.","topic":"Strait of Hormuz","kind":"fact"},{"t":277,"quote":"For over four decades, it has set out the legal framework for activities in all our oceans and seas.","topic":"Strait of Hormuz","kind":"number"},{"t":286,"quote":"The current war in the Persian Gulf has put UNCLOS to a severe stress test. The Strait of Hormuz is closed.","topic":"Strait of Hormuz","kind":"fact"},{"t":356,"quote":"The Strait of Hormuz carried around a fifth of the world's oil supplies, as well as critical supplies for other industries everywhere.","topic":"Strait of Hormuz","kind":"number"},{"t":401,"quote":"The Strait of is less than two nautical miles at its And yet nearly a quarter of the world's seaborne trade passes through the Strait of Singapore.","topic":"Straits of Malacca","kind":"number"},{"t":420,"quote":"Indonesia, and Malaysia, the three littoral states of the Straits of Malacca and Singapore, have worked with other users of these straits to keep the straits open, secure, and accessible to everyone for decades","topic":"Straits of Malacca","kind":"fact"},{"t":466,"quote":"Lower trade costs in these decades have boosted global real GDP by an estimated And in the case of low-income countries by around 33%","topic":"WTO trade","kind":"number"},{"t":528,"quote":"For Singapore trade is three times our","topic":"WTO trade","kind":"number"},{"t":560,"quote":"I would ask all of you to recollect the BBNJ agreement which entered into force this year.","topic":"WTO trade","kind":"fact"},{"t":576,"quote":"Singapore is proud that our ambassador Vina Lee presided over the negotiations that concluded this agreement by consensus.","topic":"WTO trade","kind":"self_credit"},{"t":613,"quote":"The RCEP, the Regional Comprehensive Economic Partnership, is the largest trade agreement in the world.","topic":"WTO trade","kind":"fact"},{"t":621,"quote":"The CPTPP, the Comprehensive and Progressive Trans-Pacific Partnership, now stretches from Asia to Latin America to the United Kingdom.","topic":"WTO trade","kind":"fact"},{"t":632,"quote":"And in July, 19 small and medium-sized trading nations of the Future of Investment and Trade Partnership met in Auckland","topic":"WTO trade","kind":"number"},{"t":704,"quote":"AI offers with extraordinary potential, but its capability is advancing faster than our appreciation of its risks.","topic":"AI regulation","kind":"fact"},{"t":715,"quote":"There are fundamentally three categories of risk. First, the loss of control of autonomous systems.","topic":"AI regulation","kind":"fact"},{"t":750,"quote":"It is too late to call for a halt, especially given the superpower rivalry and the huge financial incentives for companies who already have frontier","topic":"AI regulation","kind":"fact"},{"t":793,"quote":"The engine is innovation. Every one of has to continue to invest in science, the talent, and the infrastructure that will drive AI forward.","topic":"AI regulation","kind":"fact"},{"t":820,"quote":"The real productivity gains from AI comes not from the IT department, but from our businesses and workers having the skills, the tools, and the wherewithal to engineer their work processes workflow by workflow.","topic":"AI regulation","kind":"fact"},{"t":872,"quote":"And since the risks from AI do not remain confined behind borders, it means we also need rules of the road that will form a shared global understanding of how we will collectively confront this challenge.","topic":"AI regulation","kind":"fact"},{"t":887,"quote":"Just as all of us instinctively understand traffic lights the same way, whether we're here in New York or in Beijing, Moscow, or Singapore.","topic":"AI regulation","kind":"fact"},{"t":920,"quote":"The scarce resource today is not legal architecture or technology. It is trust.","topic":"AI regulation","kind":"fact"},{"t":1003,"quote":"the UN's independent international scientific panel on AI already helps to establish a common understanding based on evidence","topic":"AI regulation","kind":"fact"},{"t":1013,"quote":"The global dialogue on AI governance can help to translate that common understanding into common objectives","topic":"AI regulation","kind":"fact"},{"t":1044,"quote":"The UN, the United Nations has a critical role to play in building convergence because this is the only apex international institution with universal membership.","topic":"AI regulation","kind":"fact"},{"t":1081,"quote":"And the examples are the International Telecommunication Union which provides or the International Atomic A Energy Agency which provides verification.","topic":"AI regulation","kind":"fact"},{"t":1106,"quote":"This week we joined the call for greater safety and security of frontier AI models.","topic":"AI regulation","kind":"fact"},{"t":1111,"quote":"And I'm glad that this was led by Finland and Norway.","topic":"AI regulation","kind":"fact"},{"t":1179,"quote":"In this session, we will appoint the 10th sec- Secretary-General of the UN.","topic":"UN reform","kind":"fact"},{"t":1185,"quote":"No one today under the age of 80 has lived in a world without the United Nations.","topic":"UN reform","kind":"fact"},{"t":1258,"quote":"Currently, the International Court of Justice has its fullest docket in its At precisely the moment when the relevance and effectiveness of international law is being questioned, states continue to bring their most serious disputes before the world's principal judicial organ.","topic":"UN reform","kind":"fact"},{"t":1285,"quote":"Singapore has nominated our ambassador for international law, Rena Lee, for election as a judge of the ICJ.","topic":"UN reform","kind":"fact"},{"t":1336,"quote":"In 1945, the founders of the UN hoped that the rules could restrain power.","topic":"multilateralism","kind":"fact"}],"promises":[{"t":1115,"quote":"We will continue to contribute through platforms such as the digital pillar for the forum of small states and by making our governance frameworks and testing tools available to all.","topic":"AI regulation","kind":"promise"}],"attacks":[],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":null,"text":"I now give the floor to His Excellency Vivian Balakrishnan, Minister for Foreign Affairs of &gt;&gt; Madam President, excellencies, our world is undergoing a profound characterized by great power contestation, the wars in Ukraine, the Middle East, We're witnessing the rise of trade supply chain disruptions, worsening climate change, and a new industrial revolution driven by digital technologies, biotechnology, and renewable energy. This means we face both great peril and great promise. we are in a more polarized and fractured And one that may be unable to protect the global commons at precisely the moment that we need that protection."},{"t":77,"topic":"multilateralism","text":"Our interstate relations are increasingly dictated by raw power, where the outcomes are determined on the basis of size, leverage, and coercion. And this poses, obviously, a clear and present danger for smaller states like Singapore. the point I wanted to make is that even the more powerful states would ultimately pay a price because hard power on its own cannot secure supply chains, protect populations from pandemics, or stabilize a warming Even big powers need partners to secure their long-term national interests. The bilateral and regional arrangements can complement global frameworks. But on their own, they cannot replace shared rules that apply universally."},{"t":139,"topic":"multilateralism","text":"A system built on individual coercive bargains would inherently be more volatile and more And therefore, our thesis today is that offers a different bargain. One that is in every state's enlightened national These shared rules and norms provide They constrain the capricious exercise of power. And they maximize autonomy even when power is unequally distributed. the multilateral system today still works more often than the headlines would suggest. A few examples. The World Food Program feeds over a hundred million people a year. The common ICAO standards enable a hundred thousand flights to operate safely every day."},{"t":204,"topic":"multilateralism","text":"With the ITU, our telecommunications networks and the internet continues to operate safely, smoothly on a planetary The question is therefore not whether we need multilateralism, but how to make it fit for purpose. And I suggest three priorities. we all have to consistently comply with international law. And the norms of multilateralism. Second, we need to reform existing institutions when needed. And third, we need to collectively formulate new rules and create new institutions for new technologies. Let me deal with the first point. The consistent compliance with international law. Consider UNCLOS, the UN Convention on the Law of the Sea. In fact, UNCLOS is one of the great achievements of multilateral lawmaking."},{"t":268,"topic":"Strait of Hormuz","text":"It was concluded under the presidency of Professor Tommy Koh of Singapore, who called it the constitution for the oceans. For over four decades, it has set out the legal framework for activities in all our oceans and seas. But the current war in the Persian Gulf has put UNCLOS to a severe stress test. The Strait of Hormuz is closed. We have to collectively reject this. Transit passage through straits used for international navigation is a right for all of us. It's not a privilege subject to fees and tolls. And this is customary international law, which means it is binding on all states whether or not they consider themselves parties to UNCLOS. How we deal with the Strait of Hormuz will have implications for navigational rights and freedom around the world."},{"t":334,"topic":"Strait of Hormuz","text":"At stake is the legal architecture for freedom of navigation and overflight. And we cannot allow any single country to exercise a veto on these navigational rights and freedoms. Beyond the legal and political implications, the economic impact is also very stark. The Strait of Hormuz carried around a fifth of the world's oil supplies, as well as critical supplies for other industries everywhere. Its disruption has meant higher energy prices for all of us, broken, disrupted supply chains, and stranded seafarers. And this is why shared rules like UNCLOS matter. Defending them is not just a matter of principle or debate. It is in our collective interest. The largest economies depend on the open sea lanes as much as the smallest."},{"t":397,"topic":"Straits of Malacca","text":"And we in Singapore hold ourselves to the same standard. The Strait of is less than two nautical miles at its And yet nearly a quarter of the world's seaborne trade passes through the Strait of Singapore. Indonesia, and Malaysia, the three littoral states of the Straits of Malacca and Singapore, have worked with other users of these straits to keep the straits open, secure, and accessible to everyone for decades, including through the cooperative mechanism on the safety of navigation and environmental protection in the Straits of Malacca and Singapore. Madam President, excellencies, the second point is that we should and must reform existing institutions and processes where necessary."},{"t":459,"topic":"WTO trade","text":"In fact, free trade is another success story of the post-war multilateralism. Lower trade costs in these decades have boosted global real GDP by an estimated And in the case of low-income countries by around 33% Under the GATT and subsequently the WTO, disputes even between unequal powers could be settled by adjudication rather than the exercise of unilateral But we all know the multilateral trading system has frayed. This year's WTO conference in Yaounde could not even reach consensus on several key issues including the moratorium on the customs duties for electronic transmissions which lapsed. Tariffs and supply chain restrictions have also returned as instruments of The consequences of all this cannot be For Singapore trade is three times our For many in this hall, access to markets and technology are absolutely essential for our development."},{"t":541,"topic":"WTO trade","text":"When the rules governing trade are all of us will pay the price. I know that consensus amongst 193 states is difficult but it remains the gold standard. And I would ask all of you to recollect the BBNJ agreement which entered into force this year. This is clear evidence that even in this time we can still build common rules for shared challenges and Singapore is proud that our ambassador Vina Lee presided over the negotiations that concluded this agreement by consensus. Having said that, even when consensus is we cannot allow collective action to be held hostage or to be paralyzed. We need more flexible coalition of states and partners who are willing and able to move forward whilst remaining open to others to join when they are ready."},{"t":608,"topic":"WTO trade","text":"Such coalitions already serve large and small economies alike. The RCEP, the Regional Comprehensive Economic Partnership, is the largest trade agreement in the world. The CPTPP, the Comprehensive and Progressive Trans-Pacific Partnership, now stretches from Asia to Latin America to the United Kingdom. And in July, 19 small and medium-sized trading nations of the Future of Investment and Trade Partnership met in Auckland, not to negotiate a grand but to systematically reduce trade frictions and to strengthen supply chain Excellencies, this is not a retreat from multilateralism. It is a pragmatic and flexible effort to sustain cooperation when broader agreement is not yet while remaining open for those who are ready to join later The objective remains the same: to preserve the benefits of cooperation, widen participation over time, and ultimately bring these arrangements into the multilateral global architecture."},{"t":683,"topic":"AI regulation","text":"we must collectively formulate new rules and be prepared to create new institutions if necessary for new Artificial intelligence, which we've heard so many times from the podium this week, is arguably the most urgent AI offers with extraordinary potential, but its capability is advancing faster than our appreciation of its risks. There are fundamentally three categories of risk. First, the loss of control of autonomous systems. Second, that rogue actors could use AI to create bio weapons or other weapons of mass destruction or mass disruption. the economic, the social, the political, domestic disruptions are only just emerging."},{"t":746,"topic":"AI regulation","text":"But, excellencies, the genie is already out of the bottle. It is too late to call for a halt, especially given the superpower rivalry and the huge financial incentives for companies who already have frontier But, let me offer a metaphor of driving a high-performance car. To drive a high-performance car quickly and you need a powerful engine. But, equally, you need good brakes. And, especially if you are going to go beyond your neighborhood or cross boundaries, you need effective shared rules, traffic lights, insurance, norms of behavior, seat belts. The engine is innovation. Every one of has to continue to invest in science, the talent, and the infrastructure that will drive AI forward. For small states, this entails especially developing our people, equipping them with the skills necessary to master and deploy AI quickly, widely, at scale, and safely."},{"t":820,"topic":"AI regulation","text":"The real productivity gains from AI comes not from the IT department, but from our businesses and workers having the skills, the tools, and the wherewithal to engineer their work processes workflow by workflow. It is that's where the cutting edge of value creation arises. But, having said that, every powerful engine needs good brakes, safeguards. As the capabilities of AI advance, our safeguards must keep pace. We need rigorous testing and evaluation before deployment. We need clear limits on what autonomous systems can do, and mecha- mechanisms to intervene when they behave in ways we do not intend. And since the risks from AI do not remain confined behind borders, it means we also need rules of the road that will form a shared global understanding of how we will collectively confront this challenge."},{"t":887,"topic":"AI regulation","text":"Just as all of us instinctively understand traffic lights the same way, whether we're here in New York or in Beijing, Moscow, or Singapore. Most importantly, human beings must ultimately remain in control and accountable. Let me give you an extreme thought Do you want the nuclear button to be in the hands of a human being or an AI? Think about that. The scarce resource today is not legal architecture or technology. It is trust. Trust that the risk will be disclosed, that testing will be comprehensive and credible, and that cooperation will be inclusive and not be used to secure unilateral advantage. The technology has already become an arena for strategic competition, precisely when international cooperation is most Any durable international approach must give all stakes all stakes a meaningful Not only those who already have the most advanced models or the deepest pockets or the largest set of armaments."},{"t":968,"topic":"AI regulation","text":"So, the question is how do we build We begin with the science. Even where states have differences on governance, I believe it is possible for us to work together to collectively understand the capabilities and risk of AI models, to develop comparable methods for testing and evaluation, and to report serious quickly across borders. We are not starting from zero. If you carefully go through what we already have today, the UN's independent international scientific panel on AI already helps to establish a common understanding based on evidence. The global dialogue on AI governance can help to translate that common understanding into common objectives. And the ITU's AI for good global commission brings together leaders from government, industry, and international institutions to discuss challenges and to come up with practical solutions."},{"t":1032,"topic":"AI regulation","text":"We must urgently establish common rules and safeguards for AI, and we should build on the many ongoing discussions in different formats and And here I want to make a point. The UN, the United Nations has a critical role to play in building convergence because this is the only apex international institution with universal membership. We must explore all options including the idea of a UN framework convention on AI safeguards. We may also need an international institution that can perform for AI some of the functions that currently exist for institutions that perform this this function of setting common technical standards. And the examples are the International Telecommunication Union which provides or the International Atomic A Energy Agency which provides verification. Ultimately the global commons are best protected by collective action agreed through an inclusive process."},{"t":1101,"topic":"AI regulation","text":"And Singapore commits to contribute where we can. This week we joined the call for greater safety and security of frontier AI models. And I'm glad that this was led by Finland and Norway. We will continue to contribute through platforms such as the digital pillar for the forum of small states and by making our governance frameworks and testing tools available to all. But the work of building trust and laying the ground for global cooperation must begin now. powerful engines and good brakes and common rules do not stop us or slow us down. They give us the assurance and the confidence so that we can move faster and more effectively for the benefit of all our peoples. Madam President, excellencies, effective multilateralism requires institutions that can deliver and that begins with a reform of the UN itself. I welcome the progress of the UN 80 initiative, but reform must be strategic, not merely not merely fiscal."},{"t":1168,"topic":"UN reform","text":"Reform must strengthen the equal standing of all The goal is not a smaller UN for its own sake, but one that delivers better and more equitably. In this session, we will appoint the 10th sec- Secretary-General of the UN. No one today under the age of 80 has lived in a world without the United Nations. But the UN has to earn the conf- confidence of successive And it does this through what it not what it declares on paper. The next Secretary-General must lead a UN that turns multilateral cooperation into practical results and communicates these results in an effective way to all our people. Let me at this point also pay tribute to Secretary-General Antonio Guterres. He's a good man with the courage of his convictions. And he has ably steered this organization through some very difficult years of global division."},{"t":1232,"topic":"UN reform","text":"He has been a consistent voice for the charter, for our climate and oceans, and for the rules that hold the global commons together. Finally, Madam President, effective multilateralism requires all countries to be prepared to contribute to the institutions that sustain it. For Singapore, this begins with international law. The rule of law requires institutions to give it effect. Currently, the International Court of Justice has its fullest docket in its At precisely the moment when the relevance and effectiveness of international law is being questioned, states continue to bring their most serious disputes before the world's principal judicial organ. That's actually a good sign. That demonstrates trust in the peaceful settlement of disputes, and we must safeguard that trust. Singapore has nominated our ambassador for international law, Rena Lee, for election as a judge of the ICJ. And as a tiny small state, Singapore has been a beneficiary, has been an active practitioner, and a builder, a contributor to international law."},{"t":1301,"topic":"multilateralism","text":"We now ask for the chance to serve the cause of the rule of law. Madam President, this is the case for multilateralism. It's not some pie-in-the-sky but a hard-headed recognition that cooperation ultimately serves all of us. For every state, large or small, a world governed by rules is infinitely than one governed simply by the exercise of hard, crude power. In 1945, the founders of the UN hoped that the rules could restrain power. If we want to keep that hope alive, we must defend those very same rules that continue to serve us consistently everywhere across the globe. We have to adapt to a changing world, and we have to build new rules, new institutions, and new processes where the challenges demand."},{"t":1365,"topic":null,"text":"Thank you all very much. &gt;&gt; I thank the Foreign Minister of Singapore for his presentation."}],"compare":[{"topic":"Artificial Intelligence","share":0.3765,"mean":0.0488,"rank":3,"others":83},{"topic":"International Law & Order","share":0.1982,"mean":0.0597,"rank":15,"others":102},{"topic":"Global Trade","share":0.1733,"mean":0.0039,"rank":2,"others":7},{"topic":"UN & its reform","share":0.1045,"mean":0.2053,"rank":143,"others":170},{"topic":"Strait of Hormuz","share":0.0997,"mean":0.0026,"rank":3,"others":5},{"topic":"Maritime Security","share":0.0478,"mean":0.0045,"rank":10,"others":9}]};
